import groovy.json.JsonOutput
import groovy.json.JsonSlurper
import java.nio.charset.StandardCharsets
import org.apache.commons.io.IOUtils
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

def flowFile = session.get()
if (flowFile == null) {
    return
}

def raw = ""
session.read(flowFile, { inputStream ->
    raw = IOUtils.toString(inputStream, StandardCharsets.UTF_8)
} as InputStreamCallback)

try {
    def event = new JsonSlurper().parseText(raw)
    def amount = new BigDecimal(event.amount.toString())
    if (event.event_type == "wallet.payment.authorized" && amount >= 100G) {
        event.pipeline = "nifi-k8s-phase2"
        event.risk_tier = amount >= 1000G ? "HIGH" : "STANDARD"
        flowFile = session.write(flowFile, { outputStream ->
            outputStream.write(JsonOutput.toJson(event).getBytes(StandardCharsets.UTF_8))
        } as OutputStreamCallback)
        flowFile = session.putAttribute(flowFile, "wallet.filter", "authorized-amount-gte-100")
        session.transfer(flowFile, REL_SUCCESS)
    } else {
        flowFile = session.putAttribute(flowFile, "wallet.filter", "rejected-or-low-value")
        session.transfer(flowFile, REL_FAILURE)
    }
} catch (Exception e) {
    flowFile = session.putAttribute(flowFile, "wallet.filter.error", e.toString())
    session.transfer(flowFile, REL_FAILURE)
}
